  background: #f7f8fa;
  color: #1a1d23;
  line-height: 1.6;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

/* ─── Skip link ─────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: 0.5rem 1rem;
  background: #2563eb;
  color: #fff;
  border-radius: 0 0 6px 6px;
  font-weight: 600;
  text-decoration: none;
  z-index: 9999;
  transition: top 0.1s;
}

.skip-link:focus {
  top: 0;
}

/* ─── Header ────────────────────────────────────────────────────── */
.site-header {
  background: #fff;
  border-bottom: 1px solid #e4e7ed;
  padding: 0 1.5rem;
}

.header-inner {
  max-width: 760px;
  margin: 0 auto;
  height: 56px;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.logo {
  font-size: 1.5rem;
  line-height: 1;
}

.site-name {
  font-size: 1.125rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: #1a1d23;
}

/* ─── Hero ──────────────────────────────────────────────────────── */
.hero {
  text-align: center;
  padding: 3.5rem 1.5rem 2.5rem;
}

.hero h1 {
  font-size: clamp(1.75rem, 5vw, 2.5rem);
  font-weight: 800;
  letter-spacing: -0.03em;
  color: #0f1117;
}

.hero-subtitle {
  margin-top: 0.5rem;
  font-size: 1.05rem;
  color: #6b7280;
}

/* ─── FAQ container ─────────────────────────────────────────────── */
.faq-container {
  max-width: 760px;
  margin: 0 auto;
  padding: 0 1.5rem 4rem;
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

/* ─── Individual FAQ item ───────────────────────────────────────── */
.example {
  background: #fff;
  border: 1px solid #e4e7ed;
  border-radius: 12px;
  overflow: hidden;
  transition: box-shadow 0.15s ease, border-color 0.15s ease;
}

.example:has(.faq-trigger[aria-expanded="true"]) {
  border-color: #bfdbfe;
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.08);
}

/* ─── Trigger ───────────────────────────────────────────────────── */
.example h2 {
  font-size: 1rem; /* reset heading size; visual size set on button */
}

.faq-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1.1rem 1.25rem;
  background: transparent;
  border: none;
  cursor: pointer;
  text-align: left;
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  color: #0f1117;
  border-radius: 12px;
  transition: background 0.12s ease;
}

.faq-trigger:hover {
  background: #f0f4ff;
}

.faq-trigger:focus-visible {
  outline: 2.5px solid #2563eb;
  outline-offset: -2.5px;
  border-radius: 12px;
}

/* chevron icon injected by JS */
.faq-trigger .chevron {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  color: #6b7280;
  transition: transform 0.2s ease, color 0.15s ease;
}

.faq-trigger[aria-expanded="true"] .chevron {
  transform: rotate(180deg);
  color: #2563eb;
}

/* ─── Panel ─────────────────────────────────────────────────────── */
.details {
  padding: 0 1.25rem 1.25rem;
  border-top: 1px solid #f0f2f5;
}

.details p {
  font-size: 0.9375rem;
  color: #374151;
  line-height: 1.7;
  padding-top: 0.9rem;
}

/* ─── Footer ────────────────────────────────────────────────────── */
.site-footer {
  margin-top: auto;
  text-align: center;
  padding: 1.25rem;
  font-size: 0.875rem;
  color: #9ca3af;
  border-top: 1px solid #e4e7ed;
  background: #fff;
}

/* ─── Forced colors (high-contrast mode) ───────────────────────── */
@media (forced-colors: active) {
  .faq-trigger {
    forced-color-adjust: auto;
  }

  .faq-trigger:focus-visible {
    outline: 3px solid ButtonText;
  }

  .example {
    border: 1px solid ButtonText;
  }

  .chevron {
    forced-color-adjust: auto;
  }
}

/* ─── Reduced motion ────────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  .faq-trigger,
  .faq-trigger .chevron,
  .example {
    transition: none;
  }
}

/* ─── Reflow / narrow viewport ──────────────────────────────────── */
@media (max-width: 400px) {
  .faq-trigger {
    padding: 0.9rem 1rem;
  }

  .details {
    padding: 0 1rem 1rem;
  }
}
